  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "In this systematic review and meta-analysis, we examined the evidence on transjugular intrahepatic portosystemic shunt (TIPS) as a bridge to elective and emergency surgery in cirrhotic patients. We aimed to assess the perioperative characteristics, management approaches, and outcomes of this intervention",
      "reason": "The review objective is explicitly stated in the abstract ('We aimed to assess...'), but it is not formulated using an explicit question-formulation framework (e.g., PICO), so the element is only partially satisfied."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "The outcomes of interest were: 1. Surgery after TIPS; 2. Mortality; 3. Perioperative transfusions; and 4. Postoperative liver-related events.",
      "reason": "The population (cirrhotic patients undergoing elective and emergency surgery), intervention (preoperative TIPS), and outcomes are stated, and the comparison (TIPS vs non-TIPS) is implied in the meta-analysis description (text_14), but the planned comparisons are not explicitly presented in a formal PICO-style statement."
    }
  ],
  "confidence": 78
}

